//go:build windows

package main

// Dependency removal for the Windows uninstaller.
//
// DrawSplay pulls in two kinds of system dependencies: the Parsec Virtual
// Display Driver (extend mode) and WinUSB bindings for the Android accessory
// (AOA) USB identities. The uninstaller removes what DrawSplay installed and
// asks before removing anything that may be shared with other software:
//
//   - VDD: removed automatically when DrawSplay installed it and the Parsec
//     app is not installed; otherwise only after confirmation.
//   - WinUSB INFs generated by DrawSplay: always removed.
//   - Zadig (libwdi) WinUSB INFs for the AOA identities: only after
//     confirmation (the README points users at Zadig for these).
//   - Other vendors' drivers (e.g. Samsung, SuperDisplay) are never touched.
//
// The bundled ffmpeg runtime lives in the install directory and goes with it.

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
	"unicode/utf16"

	"golang.org/x/sys/windows/registry"
)

const (
	parsecVDDUninstallKey = `SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\ParsecVDD`
	parsecAppUninstallKey = `SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Parsec`
	vddUninstallTimeout   = 3 * time.Minute
)

// uninstallRequest carries the user's dependency choices from the
// non-elevated uninstaller to the elevated phase.
type uninstallRequest struct {
	RemoveVDD   bool `json:"removeVdd"`
	RemoveZadig bool `json:"removeZadig"`
}

// uninstallDepsPlan describes the dependencies found on this PC.
type uninstallDepsPlan struct {
	VDDPresent   bool
	VDDOwned     bool // installed by DrawSplay
	ParsecApp    bool // full Parsec app installed (shares the VDD)
	OwnedINFs    []string
	ZadigINFs    []string
	sharedPrompt []string
}

func planUninstallDeps(m installManifest) uninstallDepsPlan {
	p := uninstallDepsPlan{ParsecApp: parsecAppInstalled()}
	_, _, haveUninstaller := parsecVDDUninstaller()
	p.VDDPresent = haveUninstaller || len(scanParsecVDDInfs()) > 0
	p.VDDOwned = m.ParsecVDDOwned
	if dir, err := userStateDir(); err == nil && fileExists(filepath.Join(dir, parsecOwnedMarkerName)) {
		p.VDDOwned = true
	}
	p.OwnedINFs, p.ZadigINFs = scanAOAWinUSBInfs()
	if p.VDDPresent && p.vddShared() {
		reason := "it was already installed before DrawSplay"
		if p.ParsecApp {
			reason = "the Parsec app also uses it"
		}
		p.sharedPrompt = append(p.sharedPrompt, "• Parsec Virtual Display Driver ("+reason+")")
	}
	if len(p.ZadigINFs) > 0 {
		p.sharedPrompt = append(p.sharedPrompt, fmt.Sprintf("• WinUSB driver binding for Android accessory mode installed with Zadig (%s)", strings.Join(p.ZadigINFs, ", ")))
	}
	return p
}

func (p uninstallDepsPlan) vddShared() bool { return !p.VDDOwned || p.ParsecApp }

// request returns the elevated-phase request; removeShared is the user's
// answer for the shared components.
func (p uninstallDepsPlan) request(removeShared bool) uninstallRequest {
	return uninstallRequest{
		RemoveVDD:   p.VDDPresent && (!p.vddShared() || removeShared),
		RemoveZadig: len(p.ZadigINFs) > 0 && removeShared,
	}
}

func uninstallRequestPath(resultPath string) string { return resultPath + ".request.json" }

// removeUninstallDeps (elevated) removes the requested dependencies. Driver
// removal problems are reported as warnings: DrawSplay itself is gone either
// way and the user can remove leftovers from Device Manager.
func removeUninstallDeps(req uninstallRequest, res *uninstallResult) {
	// DrawSplay's own virtual display driver is never shared; always remove it.
	removeDrawSplayIddDriver(res)

	owned, zadig := scanAOAWinUSBInfs()
	infs := owned
	if req.RemoveZadig {
		infs = append(infs, zadig...)
	}
	pnputil := system32Path("pnputil.exe")
	for _, inf := range infs {
		if err := runPnputilHidden(pnputil, "/delete-driver "+inf+" /uninstall /force"); err != nil {
			res.Warnings = append(res.Warnings, fmt.Sprintf("remove WinUSB driver %s: %v", inf, err))
		} else {
			res.Removed = append(res.Removed, "WinUSB driver "+inf)
		}
	}
	if err := removeWinUSBSigningCerts(""); err != nil {
		res.Warnings = append(res.Warnings, fmt.Sprintf("remove DrawSplay driver-signing certificate: %v", err))
	}

	if req.RemoveVDD {
		if err := uninstallParsecVDD(); err != nil {
			res.Warnings = append(res.Warnings, fmt.Sprintf("remove Parsec Virtual Display Driver: %v", err))
		} else {
			res.Removed = append(res.Removed, "Parsec Virtual Display Driver")
		}
	}
}

// removeDrawSplayIddDriver removes DrawSplay's own virtual display devnode and
// its staged driver package(s).
func removeDrawSplayIddDriver(res *uninstallResult) {
	if err := removeIDDDriver(); err != nil {
		// Not necessarily a problem: the driver may never have been installed.
		res.Warnings = append(res.Warnings, fmt.Sprintf("remove DrawSplay virtual display device: %v", err))
	}
	pnputil := system32Path("pnputil.exe")
	packagesRemoved := true
	for _, inf := range scanDrawSplayIddInfs() {
		if err := runPnputilHidden(pnputil, "/delete-driver "+inf+" /uninstall /force"); err != nil {
			packagesRemoved = false
			res.Warnings = append(res.Warnings, fmt.Sprintf("delete driver package %s: %v", inf, err))
		} else {
			res.Removed = append(res.Removed, "DrawSplay virtual display driver "+inf)
		}
	}
	if packagesRemoved {
		if err := removeIDDSigningCerts(""); err != nil {
			res.Warnings = append(res.Warnings, fmt.Sprintf("remove virtual display signing certificates: %v", err))
		}
	} else {
		res.Warnings = append(res.Warnings, "Retained virtual display signing certificates because a driver package could not be removed; rerun uninstall after resolving the driver removal failure.")
	}
}

// scanDrawSplayIddInfs lists installed DrawSplay IddCx driver packages
// (oem*.inf) by their root hardware id.
func scanDrawSplayIddInfs() []string {
	var infs []string
	matches, _ := filepath.Glob(filepath.Join(os.Getenv("SystemRoot"), "INF", "oem*.inf"))
	for _, path := range matches {
		if data, err := os.ReadFile(path); err == nil &&
			strings.Contains(strings.ToLower(decodeINFText(data)), `root\drawsplayidd`) {
			infs = append(infs, filepath.Base(path))
		}
	}
	return infs
}

// scanAOAWinUSBInfs lists installed driver packages (oem*.inf) that bind
// WinUSB and were generated by DrawSplay or by Zadig for the AOA identities.
func scanAOAWinUSBInfs() (owned, zadig []string) {
	matches, _ := filepath.Glob(filepath.Join(os.Getenv("SystemRoot"), "INF", "oem*.inf"))
	for _, path := range matches {
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		switch classifyWinUSBInf(decodeINFText(data)) {
		case winusbInfDrawSplay:
			owned = append(owned, filepath.Base(path))
		case winusbInfZadigAOA:
			zadig = append(zadig, filepath.Base(path))
		}
	}
	return owned, zadig
}

// decodeINFText handles UTF-16LE INFs (with BOM) as well as ANSI/UTF-8.
func decodeINFText(data []byte) string {
	if len(data) >= 2 && data[0] == 0xFF && data[1] == 0xFE {
		u := make([]uint16, 0, len(data)/2)
		for i := 2; i+1 < len(data); i += 2 {
			u = append(u, uint16(data[i])|uint16(data[i+1])<<8)
		}
		return string(utf16.Decode(u))
	}
	return string(data)
}

func parsecAppInstalled() bool {
	for _, access := range []uint32{registry.WOW64_64KEY, registry.WOW64_32KEY} {
		if k, err := registry.OpenKey(registry.LOCAL_MACHINE, parsecAppUninstallKey, registry.QUERY_VALUE|access); err == nil {
			k.Close()
			return true
		}
	}
	return false
}

// parsecVDDUninstaller returns the Parsec VDD NSIS uninstaller and its
// directory from the Apps & Features entry.
func parsecVDDUninstaller() (exe, dir string, ok bool) {
	for _, access := range []uint32{registry.WOW64_64KEY, registry.WOW64_32KEY} {
		k, err := registry.OpenKey(registry.LOCAL_MACHINE, parsecVDDUninstallKey, registry.QUERY_VALUE|access)
		if err != nil {
			continue
		}
		s, _, err := k.GetStringValue("UninstallString")
		k.Close()
		if err != nil {
			continue
		}
		exe = strings.Trim(strings.TrimSpace(s), `"`)
		if fileExists(exe) {
			return exe, filepath.Dir(exe), true
		}
	}
	return "", "", false
}

// uninstallParsecVDD removes the Parsec Virtual Display Driver: it runs the
// registered NSIS uninstaller silently (`_?=<dir>` makes it run in place and
// block instead of re-spawning from %TEMP%), then deletes any remaining VDD
// driver packages and stale Apps & Features entries (several VDD versions
// may have been registered, e.g. by the Parsec app and by DrawSplay).
func uninstallParsecVDD() error {
	var problems []string
	if exe, dir, ok := parsecVDDUninstaller(); ok {
		if err := runParsecVDDUninstaller(exe, dir); err != nil {
			problems = append(problems, fmt.Sprintf("uninstaller: %v", err))
		}
	}
	for _, inf := range scanParsecVDDInfs() {
		if err := runPnputilHidden(system32Path("pnputil.exe"), "/delete-driver "+inf+" /uninstall /force"); err != nil {
			problems = append(problems, fmt.Sprintf("delete driver %s: %v", inf, err))
		}
	}
	removeStaleParsecVDDUninstallEntries()
	if len(problems) > 0 {
		return errors.New(strings.Join(problems, "; "))
	}
	return nil
}

func runParsecVDDUninstaller(exe, dir string) error {
	cmd := exec.Command(exe)
	hideChildWindow(cmd)
	cmd.SysProcAttr.CmdLine = `"` + exe + `" /S _?=` + dir
	done := make(chan error, 1)
	if err := cmd.Start(); err != nil {
		return err
	}
	go func() { done <- cmd.Wait() }()
	select {
	case err := <-done:
		if err != nil {
			return err
		}
	case <-time.After(vddUninstallTimeout):
		_ = cmd.Process.Kill()
		return fmt.Errorf("timed out after %s", vddUninstallTimeout)
	}
	for i := 0; i < 10; i++ {
		if err := os.RemoveAll(dir); err == nil {
			break
		}
		time.Sleep(500 * time.Millisecond)
	}
	return nil
}

// scanParsecVDDInfs lists installed Parsec VDD driver packages (oem*.inf).
func scanParsecVDDInfs() []string {
	var infs []string
	matches, _ := filepath.Glob(filepath.Join(os.Getenv("SystemRoot"), "INF", "oem*.inf"))
	for _, path := range matches {
		if data, err := os.ReadFile(path); err == nil && isParsecVDDInf(decodeINFText(data)) {
			infs = append(infs, filepath.Base(path))
		}
	}
	return infs
}

// removeStaleParsecVDDUninstallEntries deletes ParsecVDD Apps & Features
// entries whose uninstaller no longer exists.
func removeStaleParsecVDDUninstallEntries() {
	for _, access := range []uint32{registry.WOW64_64KEY, registry.WOW64_32KEY} {
		k, err := registry.OpenKey(registry.LOCAL_MACHINE, parsecVDDUninstallKey, registry.QUERY_VALUE|access)
		if err != nil {
			continue
		}
		s, _, _ := k.GetStringValue("UninstallString")
		k.Close()
		if exe := strings.Trim(strings.TrimSpace(s), `"`); exe == "" || !fileExists(exe) {
			// The parent handle is already bound to this registry view.
			parent, err := registry.OpenKey(registry.LOCAL_MACHINE, filepath.Dir(parsecVDDUninstallKey), registry.ALL_ACCESS|access)
			if err == nil {
				_ = registry.DeleteKey(parent, filepath.Base(parsecVDDUninstallKey))
				parent.Close()
			}
		}
	}
}

// removeUserDependencyCaches deletes per-user download caches.
func removeUserDependencyCaches() {
	tmp := os.TempDir()
	if leftovers, err := filepath.Glob(filepath.Join(tmp, "drawsplay-winusb-*")); err == nil {
		for _, p := range leftovers {
			_ = os.RemoveAll(p)
		}
	}
}
